import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.BuBU3QrY.js";const u=JSON.parse('{"title":"Part 1: Building an STM32 Development Toolchain from Scratch — Cross-Compilation Principles and Installation Guide","description":"","frontmatter":{"title":"Part 1: Building an STM32 Development Toolchain from Scratch — Cross-Compilation Principles and Installation Guide","description":"","tags":["beginner","cpp-modern","stm32f1"],"difficulty":"beginner","platform":"stm32f1","chapter":14,"order":1,"translation":{"source":"documents/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md","source_hash":"3e0fe3078ac0320a7d603f5acb8bb8d4d1dce68ee183250e7477e7fc45171b5f","translated_at":"2026-05-26T11:57:24.345125+00:00","engine":"anthropic","token_count":1569}},"headers":[],"relativePath":"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md","filePath":"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md","lastUpdated":null}'),t={name:"en/vol8-domains/embedded/00-env-setup/01-toolchain-setup.md"};function o(l,e,r,c,d,h){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="part-1-building-an-stm32-toolchain-from-scratch-—-cross-compilation-principles-and-installation-guide" tabindex="-1">Part 1: Building an STM32 Toolchain from Scratch — Cross-Compilation Principles and Installation Guide <a class="header-anchor" href="#part-1-building-an-stm32-toolchain-from-scratch-—-cross-compilation-principles-and-installation-guide" aria-label="Permalink to &quot;Part 1: Building an STM32 Toolchain from Scratch — Cross-Compilation Principles and Installation Guide&quot;">​</a></h1><blockquote><p>For everyone who wants to work with STM32 on Linux but feels dizzy from the barrage of toolchain jargon. This article documents our complete process of setting up an ARM cross-compilation environment from scratch, including why we cross-compile, what each tool does, and how to install everything on Ubuntu and Arch Linux.</p></blockquote><hr><h2 id="why-i-m-writing-this-tutorial" tabindex="-1">Why I&#39;m Writing This Tutorial <a class="header-anchor" href="#why-i-m-writing-this-tutorial" aria-label="Permalink to &quot;Why I&#39;m Writing This Tutorial&quot;">​</a></h2><p>To be honest, I couldn&#39;t stand Keil&#39;s antiquated workflow anymore. It&#39;s 2024, and we&#39;re still stuck with a closed-source IDE that only runs on Windows, featuring half-baked code completion and a debugger UI that looks like it belongs in the last century. Worst of all, it hogs several gigabytes of my C: drive. The dealbreaker for me is that I&#39;ve grown completely accustomed to my Linux development environment — writing code with Vim/Neovim, getting completions from clangd, and managing builds with CMake. This toolchain feels natural and effortless on any project.</p><p>But things aren&#39;t that simple. When I first tried to flash a program to the STM32F103C8T6 (that classic, dirt-cheap Blue Pill board) from Linux, I found that the online tutorials were an absolute disaster. Some still hand-write compilation rules in Makefiles, others pull out PlatformIO as a black box that hides everything, and some just flat out say, &quot;Just use Keil, it&#39;s not worth the hassle on Linux.&quot; The most absurd ones are the so-called &quot;from scratch&quot; guides that throw a wall of commands at you to copy-paste, without ever explaining what <code>arm-none-eabi-gcc</code> does, what newlib is, or why a linker script is necessary. If you follow along, things might work, but the moment something breaks, you have absolutely no idea where to start troubleshooting.</p><p>I spent an entire weekend tearing this toolchain apart from the inside out. After falling into countless pitfalls, I finally mapped out the entire compile-and-flash pipeline. Now I&#39;m documenting this process in full — not to give you a &quot;copy-and-paste&quot; cheat sheet, but to walk you through what each step does and why we do it. That way, when you hit an error down the road, you&#39;ll know exactly which stage went wrong, instead of searching for answers like a headless fly.</p><hr><h2 id="let-s-clear-this-up-first-what-is-cross-compilation" tabindex="-1">Let&#39;s Clear This Up First: What Is Cross-Compilation <a class="header-anchor" href="#let-s-clear-this-up-first-what-is-cross-compilation" aria-label="Permalink to &quot;Let&#39;s Clear This Up First: What Is Cross-Compilation&quot;">​</a></h2><p>Before we start typing commands, there&#39;s one concept we need to nail down — cross-compilation.</p><p>If you usually write programs that run on an x86-64 CPU, the compilation process is straightforward: you use <code>gcc</code> to compile your code, and the resulting executable runs on the very same machine. The compiler and the target platform are identical; this is called &quot;native compilation.&quot;</p><p>But the STM32F103C8T6 uses an ARM Cortex-M3 core, and its instruction set is completely different from the x86-64 in your computer. Code compiled with your standard <code>gcc</code> is complete gibberish to the STM32 — it&#39;s like reading Arabic to someone who only understands Chinese. So we need a &quot;translator&quot; — a compiler that runs on x86-64 Linux but generates ARM machine code. This is the cross-compiler.</p><p>So why is it called <code>arm-none-eabi-gcc</code>, such a long and strange name? It makes perfect sense once we break it down:</p><ul><li><code>arm</code> is the target CPU architecture; the generated code is for ARM</li><li><code>none</code> means no OS vendor (we&#39;ll get to this shortly)</li><li><code>eabi</code> stands for Embedded Application Binary Interface</li><li><code>gcc</code> is our familiar GNU Compiler Collection</li></ul><p>There&#39;s a detail here worth expanding on. The <code>none</code> field was originally meant to specify the OS vendor — for example, <code>arm-linux-eabi</code> means compiling for an ARM device running Linux. But our STM32 runs bare-metal without an OS backing it up, so we put <code>none</code> here. The difference between <code>eabi</code> and <code>eabihf</code> is that the latter supports hardware floating point, but the F103C8T6&#39;s Cortex-M3 only has a single-precision floating-point unit, so the standard <code>eabi</code> is sufficient.</p><p>Once you understand cross-compilation, you&#39;ll see why you can&#39;t just use the system&#39;s built-in <code>gcc</code>, and why you need a dedicated toolchain: the compiler, linker, debugger, <em>objcopy</em> (for converting ELF to binary), <em>size</em> (for checking firmware size) — all of these tools must be &quot;cross&quot; versions.</p><hr><h2 id="what-does-the-toolchain-look-like" tabindex="-1">What Does the Toolchain Look Like <a class="header-anchor" href="#what-does-the-toolchain-look-like" aria-label="Permalink to &quot;What Does the Toolchain Look Like&quot;">​</a></h2><p>Before we dive into installation, I want to lay out the big picture so you know exactly which pieces we need to put together.</p><p>Compiling an STM32 program and flashing it to the board requires a pipeline roughly like this:</p><p>First, at the source code level. Your C/C++ code goes through preprocessing, compilation, and assembly to become individual object files (<code>.o</code> files). This step uses <code>arm-none-eabi-gcc</code> (for C code) and <code>arm-none-eabi-g++</code> (for C++ code).</p><p>But object files alone aren&#39;t enough; they need &quot;glue&quot; to hold them together. That glue is the linker (<code>arm-none-eabi-ld</code>), whose job is to stitch all object files and libraries into a complete program according to specific rules. For STM32, the linking process is especially unique — you need to tell it where Flash starts, where RAM is located, and how to allocate the heap and stack. These rules are written in a linker script (<code>.ld</code> file). The linker places the code and data sections in the correct locations based on this &quot;map.&quot;</p><p>After linking, you get an ELF (Executable and Linkable Format) file (<code>.elf</code>), which contains code, data, symbol tables, and a bunch of other information. But STM32 Flash only understands raw binary data — it has no use for symbol tables. So we use <code>arm-none-eabi-objcopy</code> to extract the &quot;meat&quot; from the ELF file, generating a <code>.bin</code> binary file. This is the actual payload that gets flashed into the chip.</p><p>There are several options for the flashing tool. The most common is ST-Link V2, ST&#39;s official debugger/programmer, which communicates with the STM32 via SWD (Serial Wire Debug). On Linux, we need software to drive the ST-Link, and that software is OpenOCD (Open On-Chip Debugger). It plays two roles: writing firmware to Flash (flashing), and acting as a GDB Server so you can debug programs on the board using GDB.</p><p>Speaking of libraries, there&#39;s a point that often trips up beginners. ARM bare-metal programs can&#39;t directly use your computer&#39;s glibc (GNU C Library), because glibc is designed for OS environments and relies on a bunch of system calls. Embedded environments need newlib — a C standard library implementation designed specifically for bare-metal and embedded systems. More specifically, we use newlib-nano, a stripped-down version of newlib optimized for code size. After installing <code>arm-none-eabi-newlib</code>, the compiler can find headers like <code>&lt;stdint.h&gt;</code> and <code>&lt;string.h&gt;</code>, and the linker can pull in the necessary library function implementations.</p><p>The final piece is debugging. OpenOCD can run in GDB Server mode, listening on a specific port (3333 by default). You connect to it with <code>arm-none-eabi-gdb</code>, and you can single-step, set breakpoints, and inspect variables just like debugging a regular program. VSCode&#39;s Cortex-Debug plugin simply puts this entire workflow behind a graphical interface, so you don&#39;t have to type GDB commands manually.</p><p>Stringing it all together, the complete chain is: <strong>Source Code → Cross-Compilation → Linking (with linker script) → objcopy extracts binary → OpenOCD flashes → GDB debugs</strong>. Once you understand this chain, you&#39;ll know exactly which tool acts at which stage, and you can quickly pinpoint whether a problem occurred during compilation, linking, or flashing.</p><hr><h2 id="alright-let-s-get-our-hands-dirty" tabindex="-1">Alright, Let&#39;s Get Our Hands Dirty <a class="header-anchor" href="#alright-let-s-get-our-hands-dirty" aria-label="Permalink to &quot;Alright, Let&#39;s Get Our Hands Dirty&quot;">​</a></h2><p>After laying out all that conceptual groundwork, we can finally get to work. I&#39;ll cover both Ubuntu and Arch, but you&#39;ll quickly notice that the commands are pretty much the same — it&#39;s all just package manager stuff.</p><p>Let&#39;s start with Ubuntu. I&#39;m using 22.04 LTS here, but the commands for 20.04 and 24.04 are basically identical, since they share the same package repositories. Open a terminal and update the package index first — it&#39;s a good habit:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then install all the packages we need in one go:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gcc-arm-none-eabi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    gdb-arm-none-eabi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    build-essential</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Let me explain what each of these packages does. <code>gcc-arm-none-eabi</code> is a bundle that includes the cross-compiler, linker, objcopy, size, and a whole suite of tools. <code>gdb-arm-none-eabi</code> is the ARM version of GDB, used for debugging embedded programs. <code>openocd</code> we covered earlier — it handles flashing and acts as a GDB Server. <code>cmake</code> and <code>build-essential</code> are build tools, with the latter including make and other fundamental compilation utilities.</p><p>After installation, we can verify that the toolchain is actually in place:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If everything is normal, you&#39;ll see output similar to this:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-none-eabi-gcc (Ubuntu 11.3.0-1ubuntu1~22.04) 11.3.0</span></span>
<span class="line"><span>Copyright (C) 2021 Free Software Foundation, Inc.</span></span>
<span class="line"><span>This is free software; see the source for copying conditions.  There is no warranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Your version number might differ, but as long as it prints the version info, the installation was successful. Here&#39;s a small detail: Ubuntu&#39;s package name is <code>gcc-arm-none-eabi</code>, without a version number — the repository automatically selects a &quot;stable and widely used&quot; version. If you need a specific version (say, you want the latest GCC 14), you&#39;ll need to download a prebuilt toolchain from ARM&#39;s official website, manually extract it to a directory, and add that path to your <code>PATH</code> environment variable. But for an older chip like the F103C8T6, GCC 11 is more than enough — there&#39;s no need to chase the newest version.</p><hr><h2 id="the-arch-linux-route" tabindex="-1">The Arch Linux Route <a class="header-anchor" href="#the-arch-linux-route" aria-label="Permalink to &quot;The Arch Linux Route&quot;">​</a></h2><p>If you&#39;re using Arch Linux (or Manjaro, which I use), package management is even more straightforward. Arch&#39;s advantage is fast package updates, so you get a fairly recent toolchain version.</p><p>The installation command is a bit shorter than Ubuntu&#39;s:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-gcc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-binutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-gdb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openocd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>There&#39;s one difference from Ubuntu here: Arch splits the tools into multiple packages. <code>arm-none-eabi-gcc</code> is the compiler itself, <code>arm-none-eabi-binutils</code> includes ld, objcopy, size, and other utilities, and <code>arm-none-eabi-gdb</code> is the debugger. Ubuntu bundles all of these into <code>gcc-arm-none-eabi</code>, so you need to install fewer packages.</p><p>Verify that the installation succeeded:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>On Arch, you&#39;ll most likely see GCC 13 or 14, since it rolls fast:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-none-eabi-gcc (GCC) 13.2.0</span></span>
<span class="line"><span>Copyright (C) 2023 Free Software Foundation, Inc.</span></span>
<span class="line"><span>This is free software; see the source for copying conditions.  There is no warranty; not even for MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>There&#39;s a pitfall I need to warn you about in advance. After installing <code>arm-none-eabi-gcc</code> on Arch, you might find that headers like <code>&lt;stdint.h&gt;</code> are missing during compilation, or you get a <code>cannot read spec file &#39;nano.specs&#39;</code> error at link time. The reason is the same in both cases — Arch&#39;s <code>arm-none-eabi-gcc</code> package doesn&#39;t include newlib, and you need to install an extra package from the AUR:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arm-none-eabi-newlib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If you don&#39;t have <code>yay</code> installed, you&#39;ll need to set up this AUR helper first, or manually clone the PKGBUILD from the AUR to build it. I won&#39;t expand on that process — anyone using Arch should already be familiar with it.</p><p>Once newlib is installed, headers like <code>&lt;stdint.h&gt;</code> and <code>&lt;string.h&gt;</code> will be available, and <code>nano.specs</code> and <code>nosys.specs</code> will work properly. What do these two specs files do? <code>nano.specs</code> tells the linker to use newlib-nano (the stripped-down C library), while <code>nosys.specs</code> provides empty system call implementations — after all, in a bare-metal environment there&#39;s no OS, so functions like <code>read()</code> and <code>write()</code> can&#39;t actually be implemented. Using nosys.specs prevents linker errors.</p><hr><h2 id="where-are-we-now" tabindex="-1">Where Are We Now <a class="header-anchor" href="#where-are-we-now" aria-label="Permalink to &quot;Where Are We Now&quot;">​</a></h2><p>At this point, our toolchain installation is complete. Your system should now have:</p><ul><li>Cross-compiler (<code>arm-none-eabi-gcc/g++</code>)</li><li>Linker and toolchain utilities (<code>arm-none-eabi-ld</code>, <code>objcopy</code>, <code>size</code>)</li><li>Debugger (<code>arm-none-eabi-gdb</code>)</li><li>Flashing tool (OpenOCD)</li><li>Build system (CMake)</li><li>C standard library (newlib)</li></ul><p>But tools alone aren&#39;t enough. In the next article, we&#39;ll cover project structure — how to get ST&#39;s official HAL library, that tricky submodule problem, which startup file to pick, and how to write a linker script. That&#39;s where the real minefield is, but for now, let&#39;s make sure the foundation is solid.</p><p>You can go ahead and verify that all tools can be invoked normally:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证编译器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证调试器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证烧录工具</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 验证 CMake</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>If all of these commands print their version information, congratulations — you&#39;ve cleared the toolchain installation hurdle. In the next article, we&#39;ll jump straight into project structure and start building a real STM32 C++ project.</p>`,62)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
